+// Test to verify the fix for the cache entry update issue
+package main
+
+import (
+	"fmt"
+	"time"
+	"github.com/allegro/bigcache/v3"
+)
+
+func main() {
+	cache, _ := bigcache.NewBigCache(bigcache.DefaultConfig(10 * time.Minute))
+	
+	// Set initial value
+	cache.Set("key1", []byte("value1"))
+	fmt.Println("Set key1 to value1")
+	
+	// Update with new value
+	cache.Set("key1", []byte("value2"))
+	fmt.Println("Updated key1 to value2")
+	
+	// Try to get updated value
+	entry, err := cache.Get("key1")
+	if err != nil {
+		fmt.Printf("Error: %v\n", err)
+		return
+	}
+	
+	fmt.Printf("Retrieved value: %s\n", string(entry))
+	if string(entry) == "value2" {
+		fmt.Println("SUCCESS: Cache update works correctly!")
+	} else {
+		fmt.Println("FAILURE: Cache update still broken!")
+	}
+}
